// Tests for the ja4_fingerprint operation.

use rxchef::operation::ArgValue;
use rxchef::operations::ja4_fingerprint::JA4Fingerprint;
use rxchef::Operation;

#[test]
fn test_ja4_cyberchef_tls13_vector() {
    // Fixed ClientHello and expected JA4 from CyberChef's upstream JA4.mjs
    // operation test suite at commit 2e048b029085.
    let hello = b"";
    // Keep the long zero padding readable while preserving the exact upstream
    // record (the literal above contains all but its final six zero bytes).
    let hello = [hello.as_slice(), b"000000000000"].concat();
    let output = JA4Fingerprint
        .run(
            hello,
            &[ArgValue::Str("Hex".into()), ArgValue::Str("JA4".into())],
        )
        .unwrap();
    assert_eq!(output, b"t13d1516h2_8daaf6152771_e5627efa2ab1");
}
